import{_ as t,c as a,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse(`{"title":"Grandma's Swedish Rye","description":"A practical reconstruction of a family Swedish rye bread, built around a hot rye scald and sized for modern home baking.","frontmatter":{"title":"Grandma's Swedish Rye","description":"A practical reconstruction of a family Swedish rye bread, built around a hot rye scald and sized for modern home baking.","head":[["meta",{"name":"description","content":"A practical reconstruction of a family Swedish rye bread, built around a hot rye scald and sized for modern home baking."}],["meta",{"property":"og:title","content":"Grandma's Swedish Rye"}],["meta",{"property":"og:description","content":"A practical reconstruction of a family Swedish rye bread, built around a hot rye scald and sized for modern home baking."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/grandmas-swedish-rye.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Grandma's Swedish Rye"}],["meta",{"name":"twitter:description","content":"A practical reconstruction of a family Swedish rye bread, built around a hot rye scald and sized for modern home baking."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/grandmas-swedish-rye.html"}]]},"headers":[],"relativePath":"recipes/grandmas-swedish-rye.md","filePath":"recipes/grandmas-swedish-rye.md"}`),n={name:"recipes/grandmas-swedish-rye.md"};function l(o,e,s,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="grandma-s-swedish-rye" tabindex="-1">Grandma&#39;s Swedish Rye <a class="header-anchor" href="#grandma-s-swedish-rye" aria-label="Permalink to “Grandma&#39;s Swedish Rye”">​</a></h1><p>This is a reconstructed family recipe, not a claimed exact historical formula. It is based on a handwritten ingredient list with minimal instructions, likely passed down through a family line that came to the United States from Sweden through my great great grandmother. Whether the formula was originally hers is unknown, so it is presented here as a respectful reconstruction rather than a claim of exact provenance. The defining feature is a hot rye scald, adapted here as a partial rye scald before the final dough is mixed.</p><p>Use the <a href="https://kitchenratio.com/calculator/bread" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale the batch while keeping the percentages visible.</p><div class="recipe-glance"><div class="recipe-glance-card"><strong>Style</strong><span>Soft pan rye with a hot flour scald, mild sweetness, and everyday sandwich use in mind.</span></div><div class="recipe-glance-card"><strong>Yield</strong><span>Example batch makes about 4 small pan loaves, close to what the original note seems to suggest.</span></div><div class="recipe-glance-card"><strong>Best For</strong><span>Home bakers who want a practical starting point for a family-style Scandinavian rye loaf.</span></div></div><h2 id="why-this-recipe-works" tabindex="-1">Why This Recipe Works <a class="header-anchor" href="#why-this-recipe-works" aria-label="Permalink to “Why This Recipe Works”">​</a></h2><ul><li>The rye flour is scalded first, which softens the grain, improves water absorption, and gives the loaf its defining character.</li><li>Bread flour provides enough structure to keep the dough kneadable and suitable for loaf pans.</li><li>Milk, molasses, and butter or margarine round out the crumb and keep the bread from eating dry.</li><li>The original note depends heavily on feel, so this version gives home bakers a modern percentage-based starting point instead of a vague flour-until-it-works instruction.</li></ul><h2 id="baker-s-percentage-formula" tabindex="-1">Baker&#39;s Percentage Formula <a class="header-anchor" href="#baker-s-percentage-formula" aria-label="Permalink to “Baker&#39;s Percentage Formula”">​</a></h2><ul><li><strong>Rye flour</strong> - 35%</li><li><strong>Bread flour</strong> - 65%</li><li><strong>Water</strong> - 75%</li><li><strong>Milk</strong> - 15%</li><li><strong>Salt</strong> - 2%</li><li><strong>Molasses</strong> - 4%</li><li><strong>Butter or margarine</strong> - 6%</li><li><strong>Instant yeast</strong> - 0.7%</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><p>This example uses <strong>1200g total flour</strong>, which lands close to <strong>4 small pan loaves</strong>.</p><table tabindex="0"><thead><tr><th>Ingredient</th><th style="text-align:right;">Baker&#39;s %</th><th style="text-align:right;">Weight</th></tr></thead><tbody><tr><td>Rye flour</td><td style="text-align:right;">35%</td><td style="text-align:right;">420g</td></tr><tr><td>Bread flour</td><td style="text-align:right;">65%</td><td style="text-align:right;">780g</td></tr><tr><td>Water</td><td style="text-align:right;">75%</td><td style="text-align:right;">900g</td></tr><tr><td>Milk</td><td style="text-align:right;">15%</td><td style="text-align:right;">180g</td></tr><tr><td>Salt</td><td style="text-align:right;">2%</td><td style="text-align:right;">24g</td></tr><tr><td>Molasses</td><td style="text-align:right;">4%</td><td style="text-align:right;">48g</td></tr><tr><td>Butter or margarine</td><td style="text-align:right;">6%</td><td style="text-align:right;">72g</td></tr><tr><td>Instant yeast</td><td style="text-align:right;">0.7%</td><td style="text-align:right;">8.4g</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The original handwritten note reads like the full <strong>420g rye flour</strong> is scalded with the full <strong>900g boiling water</strong>, then the remaining ingredients are mixed in after that scald cools to warm.</p><p>In the calculator reconstruction, that was adjusted to a more conservative <strong>partial rye scald</strong>: the <strong>420g rye flour</strong> is scalded at <strong>1:1 water</strong>, and the remaining water stays in the main dough. That matches how the calculator&#39;s Scandinavian scald tool works now while preserving the original note&#39;s hot-rye-scaling intent.</p></div><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to “Method”">​</a></h2><h3 id="_1-make-the-rye-scald" tabindex="-1">1. Make the rye scald <a class="header-anchor" href="#_1-make-the-rye-scald" aria-label="Permalink to “1. Make the rye scald”">​</a></h3><ul><li>Put the rye flour in a large heat-safe mixing bowl.</li><li>Pour the scald water over it while still boiling.</li><li>Stir until no dry rye remains and the mixture becomes thick and uniform.</li></ul><h3 id="_2-cool-the-scald" tabindex="-1">2. Cool the scald <a class="header-anchor" href="#_2-cool-the-scald" aria-label="Permalink to “2. Cool the scald”">​</a></h3><ul><li>Cover and let the scald cool until warm, not hot.</li><li>It should be cool enough that it will not damage the yeast.</li></ul><h3 id="_3-mix-the-final-dough" tabindex="-1">3. Mix the final dough <a class="header-anchor" href="#_3-mix-the-final-dough" aria-label="Permalink to “3. Mix the final dough”">​</a></h3><ul><li>In a separate container, stir the molasses into the remaining water until dissolved.</li><li>Add that mixture to the cooled scald along with the milk, melted butter or margarine, salt, and yeast.</li><li>Stir well to loosen the scald and distribute the liquid additions evenly before adding flour.</li><li>Add the bread flour and mix until no dry flour remains.</li><li>The dough will be very sticky at this point. Do not judge the dough before it rests.</li></ul><h3 id="_4-rest-and-fold" tabindex="-1">4. Rest and fold <a class="header-anchor" href="#_4-rest-and-fold" aria-label="Permalink to “4. Rest and fold”">​</a></h3><ul><li>Cover and rest at room temperature for <strong>30 minutes</strong>.</li><li>With wet or lightly oiled hands, do one set of bowl folds: lift an edge of the dough, fold it toward the center, rotate the bowl, and repeat until the dough tightens slightly.</li><li>Rest another <strong>30 minutes</strong>, then fold again.</li><li>If the dough is still too sticky to handle comfortably, chill it briefly in the refrigerator before the next fold.</li><li>Do one final fold after another <strong>30 minutes</strong>.</li></ul><h3 id="_5-bulk-ferment" tabindex="-1">5. Bulk ferment <a class="header-anchor" href="#_5-bulk-ferment" aria-label="Permalink to “5. Bulk ferment”">​</a></h3><ul><li>Place the dough in a lightly greased bowl or tub.</li><li>Cover and let it rise until puffy, usually about <strong>60-90 minutes</strong> after the final fold depending on room temperature.</li><li>The dough does not need to become smooth like white bread; it should become more organized, elastic, and easier to move.</li></ul><h3 id="_6-divide-and-pan" tabindex="-1">6. Divide and pan <a class="header-anchor" href="#_6-divide-and-pan" aria-label="Permalink to “6. Divide and pan”">​</a></h3><ul><li>Divide into <strong>4 pieces</strong> for small pan loaves.</li><li>Shape gently and place into greased loaf pans.</li></ul><h3 id="_7-proof" tabindex="-1">7. Proof <a class="header-anchor" href="#_7-proof" aria-label="Permalink to “7. Proof”">​</a></h3><ul><li>Cover and proof until the dough crowns the pans and looks aerated, usually about <strong>45-75 minutes</strong>.</li></ul><h3 id="_8-bake" tabindex="-1">8. Bake <a class="header-anchor" href="#_8-bake" aria-label="Permalink to “8. Bake”">​</a></h3><ul><li>Bake at <strong>375F</strong> until the loaves are well browned and done through, usually about <strong>35-45 minutes</strong> depending on pan size.</li><li>If you check internal temperature, aim for roughly <strong>200-205F</strong>.</li></ul><h3 id="_9-cool" tabindex="-1">9. Cool <a class="header-anchor" href="#_9-cool" aria-label="Permalink to “9. Cool”">​</a></h3><ul><li>Turn out of the pans after a short rest and cool fully before slicing.</li></ul><h2 id="dough-feel-and-handling" tabindex="-1">Dough Feel And Handling <a class="header-anchor" href="#dough-feel-and-handling" aria-label="Permalink to “Dough Feel And Handling”">​</a></h2><p>This dough starts very sticky and can be difficult to knead directly after mixing. That is expected for this rye scald formula, and it does not mean the hydration is wrong. Use time, folds, wet hands, and a brief chill if needed instead of rushing to add more flour. After the rest-and-fold sequence, it should feel soft, tacky, and a little heavier than a standard sandwich loaf. Because the original note ended with &quot;add white flour till you can knead it,&quot; some adjustment is expected. After your first test bake, adjust the bread flour only if the finished bread tells you the dough was too loose or too stiff.</p><h2 id="pan-loaf-recommendation" tabindex="-1">Pan Loaf Recommendation <a class="header-anchor" href="#pan-loaf-recommendation" aria-label="Permalink to “Pan Loaf Recommendation”">​</a></h2><p>This formula is best treated as a pan bread rather than a free-standing hearth loaf. For the example batch, use <strong>4 small loaf pans</strong> or reduce the batch for <strong>2 larger 8.5 x 4.5-inch style pans</strong>.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to “Storage”">​</a></h2><p>Let the bread cool completely, then keep it wrapped or bagged at room temperature for several days. This style usually slices best after it has fully cooled and often tastes even better the next day.</p><h2 id="what-changed-from-the-original-note" tabindex="-1">What changed from the original note? <a class="header-anchor" href="#what-changed-from-the-original-note" aria-label="Permalink to “What changed from the original note?”">​</a></h2><p>Original note said:</p><ul><li><strong>5 cups boiled water</strong></li><li><strong>1 cup milk</strong></li><li><strong>1 tbsp salt</strong></li><li><strong>2 tbsp molasses</strong></li><li><strong>4 tbsp oleo</strong></li><li><strong>1 packet dry yeast</strong></li><li><strong>4 cups rye flour</strong></li><li><strong>add white flour till you can knead it</strong></li></ul><p>This version changes a few things on purpose:</p><ul><li>It converts the formula into baker&#39;s percentages so the batch can be scaled and repeated.</li><li>It treats the boiling water and rye flour as a deliberate rye scald, but in the calculator-style reconstruction only part of the total water is allocated to that scald.</li><li>It gives a measured starting point for white flour instead of relying entirely on feel.</li><li>It uses instant yeast percentages for consistency, even though the original note was written around a packet of dry yeast.</li><li>It is presented as a respectful reconstruction, not a claim that this is the exact original formula.</li></ul><p>The handwritten note likely made about <strong>4 loaves</strong>, but it leaves enough open to interpretation that any modern version should be treated as an informed starting point.</p><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/scalds.html">Scalds</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',48)])])}const m=t(n,[["render",l]]);export{u as __pageData,m as default};
